use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/chunk-grouping176";fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!r("runs").exists());let oldroot="/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175";let inv=load(format!("{oldroot}/proof-inventory.json"));let mut bindings=Vec::new();let mut pins:BTreeMap<String,String>=serde_json::from_value(load(r("pins.json"))).unwrap();for c in load(r("cases.json")).as_array().unwrap(){let v=inv.as_array().unwrap().iter().find(|v|v["image_sha256"]==c["image_sha256"]).unwrap();let name=v["name"].as_str().unwrap();let stdout=format!("{oldroot}/runs/verify-{name}/stdout.log");let exit=format!("{oldroot}/runs/verify-{name}/exit.json");let e=load(&exit);assert_eq!(e["success"],true);assert_eq!(hash(&stdout),e["stdout_sha256"]);let text=fs::read_to_string(&stdout).unwrap();let lines=text.lines().filter(|l|l.starts_with("VERIFIED ")).collect::<Vec<_>>();assert_eq!(lines.len(),1);let f=lines[0].split_whitespace().skip(1).map(|s|s.split_once('=').unwrap()).collect::<BTreeMap<_,_>>();assert_eq!(f["image_sha256"],c["image_sha256"].as_str().unwrap());assert_eq!(f["proof_sha256"],v["proof_sha256"].as_str().unwrap());bindings.push(json!({"image_sha256":f["image_sha256"],"vk_sha256":f["vk_sha256"],"prior_verified_receipt":stdout}));for p in[stdout,exit]{pins.insert(p.clone(),hash(p));}}
 fs::write(r("vk-bindings.json"),serde_json::to_vec_pretty(&bindings).unwrap()).unwrap();let source=fs::read_to_string(r("campaign.rs")).unwrap().replace("/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175/proof-inventory.json","/home/ubuntu/src/zopro-perf-work/chunk-grouping176/vk-bindings.json");fs::write(r("finish-campaign.rs"),source).unwrap();for p in["vk-bindings.json","finish-campaign.rs","bind-vk.rs","bind-vk"]{pins.insert(r(p).display().to_string(),hash(r(p)));}fs::write(r("pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();println!("Bound all8vk hashes to checked historical Gnark receipts before capture; no proof rerun");}
